#!/bin/sh
# =============================================================================
# MCT Docker Entrypoint Script
# =============================================================================
# This script processes environment variables and starts the MCT server.
# =============================================================================

set -e

# -----------------------------------------------------------------------------
# EULA Check
# -----------------------------------------------------------------------------
if [ "$MCTOOLS_I_ACCEPT_EULA_AT_MINECRAFTDOTNETSLASHEULA" != "true" ]; then
  echo "============================================================"
  echo "ERROR: You must accept the Minecraft EULA to use this server."
  echo ""
  echo "Please read the EULA at: https://minecraft.net/eula"
  echo ""
  echo "To accept, set the environment variable:"
  echo "  MCTOOLS_I_ACCEPT_EULA_AT_MINECRAFTDOTNETSLASHEULA=true"
  echo ""
  echo "Example:"
  echo "  docker run -e MCTOOLS_I_ACCEPT_EULA_AT_MINECRAFTDOTNETSLASHEULA=true ..."
  echo "============================================================"
  exit 1
fi

# -----------------------------------------------------------------------------
# Build MCT Command
# -----------------------------------------------------------------------------
build_mct_command() {
  CMD="mct"

  # Add the subcommand (default: serve)
  if [ -n "$1" ]; then
    CMD="$CMD $1"
    shift
  else
    CMD="$CMD serve"
  fi

  # Add passcodes if set
  if [ -n "$MCTOOLS_ADMIN_PASSCODE" ]; then
    CMD="$CMD --adminpc $MCTOOLS_ADMIN_PASSCODE"
  fi

  if [ -n "$MCTOOLS_UPDATE_PASSCODE" ]; then
    CMD="$CMD --updatepc $MCTOOLS_UPDATE_PASSCODE"
  fi

  if [ -n "$MCTOOLS_DISPLAY_PASSCODE" ]; then
    CMD="$CMD --displaypc $MCTOOLS_DISPLAY_PASSCODE"
  fi

  # Add server configuration
  if [ -n "$MCTOOLS_PORT" ]; then
    CMD="$CMD --port $MCTOOLS_PORT"
  fi

  if [ -n "$MCTOOLS_SLOT" ]; then
    CMD="$CMD --slot $MCTOOLS_SLOT"
  fi

  if [ -n "$MCTOOLS_DOMAIN" ]; then
    CMD="$CMD --domain $MCTOOLS_DOMAIN"
  fi

  if [ -n "$MCTOOLS_FEATURES" ]; then
    CMD="$CMD --features $MCTOOLS_FEATURES"
  fi

  if [ -n "$MCTOOLS_TITLE" ]; then
    CMD="$CMD --title \"$MCTOOLS_TITLE\""
  fi

  if [ -n "$MCTOOLS_MOTD" ]; then
    CMD="$CMD --motd \"$MCTOOLS_MOTD\""
  fi

  # Add data directory
  if [ -n "$MCTOOLS_DATA_DIR" ]; then
    CMD="$CMD -i $MCTOOLS_DATA_DIR/server"
    CMD="$CMD --world $MCTOOLS_DATA_DIR/worlds"
    CMD="$CMD --clidata $MCTOOLS_DATA_DIR/cli"
  fi

  # Add verbose flag if set
  if [ "$MCTOOLS_LOG_VERBOSE" = "true" ]; then
    CMD="$CMD --verbose"
  fi

  # Add any remaining arguments
  for arg in "$@"; do
    CMD="$CMD $arg"
  done

  echo "$CMD"
}

# -----------------------------------------------------------------------------
# Main
# -----------------------------------------------------------------------------
echo "============================================================"
echo "MCT (Minecraft Creator Tools) Docker Container"
echo "============================================================"
echo "EULA accepted: $MCTOOLS_I_ACCEPT_EULA_AT_MINECRAFTDOTNETSLASHEULA"
echo "Port: ${MCTOOLS_PORT:-6126}"
echo "Slot: ${MCTOOLS_SLOT:-0}"
echo "Title: ${MCTOOLS_TITLE:-Minecraft Server}"
echo "============================================================"

# Build and execute the command
MCT_CMD=$(build_mct_command "$@")
echo "Starting: $MCT_CMD"
echo "============================================================"

# Execute the command
exec sh -c "$MCT_CMD"
